  "measure_id": "MEAS-24B5746B",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Prohibits physicians from performing an abortion after 15 weeks of gestation, allowing exceptions only to prevent the pregnant woman's death or to avoid a serious risk of substantial and irreversible physical impairment of a major bodily function."
    }
  ],
  "findings": [
    {
      "id": "f1",
      "clause_id": "§1",
      "concern_id": "C35",
      "effect": "costs",
      "direction": null,
      "quote": "No physician may perform an abortion after 15 weeks of gestation, except when necessary to prevent the death of the pregnant woman or serious risk of substantial and irreversible physical impairment of a major bodily function.",
      "mechanism": "Bans abortion after 15 weeks of gestation, restricting access earlier than the current standard of fetal viability.",
      "certainty": "stated"
    },
    {
      "id": "f2",
      "clause_id": "§1",
      "concern_id": "C36",
      "effect": "advances",
      "direction": null,
      "quote": "No physician may perform an abortion after 15 weeks of gestation, except when necessary to prevent the death of the pregnant woman or serious risk of substantial and irreversible physical impairment of a major bodily function.",
      "mechanism": "Expands legal protections for prenatal life by shifting the prohibition on abortion to 15 weeks of gestation from fetal viability.",
      "certainty": "stated"
    }
  ],
  "analysis": [
    {
      "clause_id": "§1",
      "question_id": "Q1",
      "answer": "Current law allows abortion at any point before fetal viability. The measure changes this by prohibiting physicians from performing abortions after 15 weeks of gestation, with narrow exceptions for the life and physical health of the pregnant woman.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q4",
      "answer": "Patients seeking abortions after 15 weeks will likely travel to other states where the procedure remains legal, seek unregulated medication, or carry pregnancies to term. Physicians may alter their practices or hesitate to intervene in medical emergencies near or past the 15-week mark due to legal uncertainty regarding the exceptions.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q5",
      "answer": "The measure addresses the gestational timeline of legal abortion, restricting it earlier in pregnancy. It reaches this by directly forbidding physicians from performing the procedure after 15 weeks.",
      "disputed": false
    },
    {
      "clause_id": "§1",
      "question_id": "Q6",
      "answer": "The state gains the power to restrict abortions at an earlier stage. Physicians are granted the discretion, albeit under legal threat, to determine whether a patient's medical condition meets the strict criteria required to qualify for an exception.",
      "disputed": false
    }
  ],
  "flags": [
    {
      "clause_id": "§1",
      "flag_id": "F1",
      "quote": "serious risk of substantial and irreversible physical impairment of a major bodily function",
      "note": "This phrase relies on clinical judgment without defining the specific conditions or the exact degree of risk required, which may create legal and medical uncertainty in emergency situations."
    }
  ],
